  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleanedText);

const session = $('JSON of Page type and their conditions').first().json.existing_session;
const updated = parsed.updated_existing_session || {};

// HARD COMPLETION CHECK (system, not AI)
if (
  session["Page Type"] &&
  session["Page Name"] &&
  session["Page Title"] &&
  session["Page Slug"] &&
  !session.Completed
) {
  updated.Completed = "true";
}

return [{
  json: {
    chat_input: parsed.prompt_for_user,
    updated_existing_session: updated
  }
}];

